/* port: file-local helper for both Rotate_Zaxis overloads (the ELF inlines the same body
 * into each): rotates the quad's four distinct vertices about its centre by the matrix r. */
static void c2dbitmappoly_rotate(C2DPoly* tris)
{
	f32 (*v0)[4] = tris[0].m_vertex;
	f32 (*v1)[4] = tris[1].m_vertex;

	/* ELF quirk: the centre is (a - b) / 2 + max(a, b) of the tri-0 vertices 1/2 (x) and
	 * 0/1 (y): the midpoint only while vertex 1 is left of 2 and vertex 0 above 1 */
	f32 cx = (v0[1][0] - v0[2][0]) * 0.5f + (v0[1][0] <= v0[2][0] ? v0[2][0] : v0[1][0]);
	f32 cy = (v0[0][1] - v0[1][1]) * 0.5f + (v0[0][1] <= v0[1][1] ? v0[1][1] : v0[0][1]);
	f32* pts[4] = { v0[0], v0[1], v0[2], v1[2] };

	for (int i = 0; i < 4; i++)
	{
		pts[i][0] -= cx;
		pts[i][1] -= cy;
	}

	for (int i = 0; i < 4; i++)
	{
		f32 x = pts[i][0];
		f32 y = pts[i][1];
		pts[i][0] = y * r[1] + x * r[0];
		pts[i][1] = y * r[3] + x * r[2];
	}

	for (int i = 0; i < 4; i++)
	{
		pts[i][0] += cx;
		pts[i][1] += cy;
	}

	/* triangle 1 shares vertices 0 and 2 */
	for (int c = 0; c < 4; c++)
	{
		v1[0][c] = v0[0][c];
		v1[1][c] = v0[2][c];
	}
}

/* @socom-skeleton stub Rotate_Zaxis__13C2DBitmapPolyFf */
void C2DBitmapPoly::Rotate_Zaxis(float degrees)
{
	/* 0x2fdd30: rotate about the quad's centre by degrees (r keeps the matrix) */
	f32 s = sinf(degrees * 0.017453292f);
	f32 c = cosf(degrees * 0.017453292f);

	r[2] = s;
	r[1] = -s;
	r[0] = c;
	r[3] = c;
	c2dbitmappoly_rotate(m_tris);
}

/* @socom-skeleton stub Rotate_Zaxis__13C2DBitmapPolyFff */
void C2DBitmapPoly::Rotate_Zaxis(float sine, float cosine)
{
	/* 0x2fda90: as Rotate_Zaxis(degrees) with the sine and cosine given */
	r[1] = -sine;
	r[0] = cosine;
	r[2] = sine;
	r[3] = cosine;
	c2dbitmappoly_rotate(m_tris);
}

/* port: 0x2fd190 (declared in ztwod.h) */
void C2DBitmapPoly::GetAssetLibs(C2D::CLibList& libs)
{
	/* 0x2fd190: the texture's asset library (ELF quirk: added only when the search result
	 * is a NULL pointer, see C2DBitmap::GetAssetLibs), then the children's */
	if (m_texture != NULL && m_texture->m_AssetLib != NULL)
	{
		zdb::CAssetLib* lib = m_texture->m_AssetLib;
		zdb::CAssetLib** i = libs.data();
		zdb::CAssetLib** last = i + libs.size();

		while (i != last && *i != lib)
			i++;

		if (i == NULL)
			libs.insert(libs.end(), lib);
	}

	for (auto c = begin(); c != end(); ++c)
		(*c)->GetAssetLibs(libs);
}

/* @socom-skeleton stub SetSegments__15C2DWidePolylineFP6CPtItrf */
void C2DWidePolyline::SetSegments(CPtItr *it, float width)
{
	/* 0x2fd370: one quad (a new C2DBitmapPoly, untextured) per segment of the iterator's
	 * points, width wide: its start edge is the previous quad's end edge, a joint between two
	 * segments is mitred (the offset along the bisector of the two half-width normals, scaled
	 * so it stands half the width off both segments), the last end is square. The quads go to
	 * _vecSegments; the caller colours them. Fewer than two points make nothing.
	 * (CPnt2D$1514 of this unit, the ELF's two-float point, is PNT2D here.) */
	if (!it->IsValid())
		return;

	PNT2D a = it->GetPt();
	it->Advance();

	if (!it->IsValid())
		return;

	PNT2D b = it->GetPt();
	f32 half = 0.5f * width;

	/* the current segment a -> b and its half-width normal n (d.y, -d.x) */
	PNT2D seg0 = a;
	PNT2D seg1 = b;
	f32 dx = b.x - a.x;
	f32 dy = b.y - a.y;
	f32 k = half / (f32)sqrt((double)(dx * dx + dy * dy));
	f32 nx = dy * k;
	f32 ny = dx * -k;

	PNT2D prevL, prevR, curL, curR;
	prevL.x = seg0.x + nx;
	prevL.y = seg0.y + ny;
	prevR.x = seg0.x - nx;
	prevR.y = seg0.y - ny;

	for (;;)
	{
		it->Advance();

		if (!it->IsValid())
		{
			/* the last end: square */
			curL.x = seg1.x + nx;
			curL.y = seg1.y + ny;
			curR.x = seg1.x - nx;
			curR.y = seg1.y - ny;
		}
		else
		{
			PNT2D c = it->GetPt();
			f32 ex = c.x - b.x;
			f32 ey = c.y - b.y;
			f32 k2 = half / (f32)sqrt((double)(ex * ex + ey * ey));
			f32 n2x = ey * k2;
			f32 n2y = ex * -k2;

			/* the mitre: the mean of the two offset points, pushed out to half the width */
			PNT2D q1, q0;
			q1.x = b.x + n2x;
			q1.y = b.y + n2y;
			q0.x = seg1.x + nx;
			q0.y = seg1.y + ny;
			f32 vx = (q0.x + q1.x) * 0.5f - b.x;
			f32 vy = (q0.y + q1.y) * 0.5f - b.y;
			f32 s = (0.25f * (width * width)) / (vx * vx + vy * vy);
			f32 ox = vx * s;
			f32 oy = vy * s;
			curL.x = b.x + ox;
			curL.y = b.y + oy;
			curR.x = b.x - ox;
			curR.y = b.y - oy;

			/* the next segment b -> c */
			seg0 = b;
			seg1 = c;
			b = c;
			nx = n2x;
			ny = n2y;
		}

		C2DBitmapPoly* quad = new C2DBitmapPoly;
		_vecSegments.push_back(quad);
		quad->m_tris[0].SetPos(prevL.x, prevL.y, prevR.x, prevR.y, curL.x, curL.y);
		quad->m_tris[1].SetPos(prevL.x, prevL.y, curL.x, curL.y, curR.x, curR.y);

		if (!it->IsValid())
			return;

		prevL = curL;
		prevR = curR;
	}
}
